const D:usize=8;const L:usize=26;const INF:i64=1152921504606846976;
fn put64(o:[*]u8,x:i64)void{const b:u64=@bitCast(x);for(0..8)|j|o[j]=@truncate(b>>@intCast(8*j));}
export fn concave_gap_alignment_global(input_opt:?[*]const i64,length:usize,output_opt:?[*]u8,capacity:usize)i64{
 if(input_opt==null or length<5 or length>L)return -1;const in=input_opt.?;const nr=in[0];const mr=in[1];if(nr<1 or nr>8 or mr<1 or mr>8)return -1;const n:usize=@intCast(nr);const m:usize=@intCast(mr);const g=@max(n,m);if(length!=2+n+m+g)return -1;var x:[D]i64=@splat(0);var y:[D]i64=@splat(0);var w:[D]i64=@splat(0);var p:usize=2;for(0..n)|i|{x[i]=in[p];p+=1;if(x[i]<0 or x[i]>3)return -1;}for(0..m)|j|{y[j]=in[p];p+=1;if(y[j]<0 or y[j]>3)return -1;}var slope=INF;for(0..g)|k|{w[k]=in[p];p+=1;if(w[k]<0 or w[k]>100)return -1;var prev:i64=0;if(k>0)prev=w[k-1];const delta=w[k]-prev;if(k>0 and (w[k]<w[k-1] or delta>slope))return -1;slope=delta;}if(output_opt==null or capacity<8)return -2;var dp:[81]i64=@splat(INF);dp[0]=0;for(0..n+1)|i|{for(0..m+1)|j|{if(i==0 and j==0)continue;var best=INF;if(i>0 and j>0){var mismatch:i64=0;if(x[i-1]!=y[j-1])mismatch=1;const cost=dp[(i-1)*9+j-1]+mismatch;if(cost<best)best=cost;}for(1..i+1)|gap|{const cost=dp[(i-gap)*9+j]+w[gap-1];if(cost<best)best=cost;}for(1..j+1)|gap|{const cost=dp[i*9+j-gap]+w[gap-1];if(cost<best)best=cost;}dp[i*9+j]=best;}}put64(output_opt.?,dp[n*9+m]);return 8;
}
